<template><AppLayout page-title="Prendre un rendez-vous"><div class="grid-2"><section class="card"><h3>Choisir un médecin</h3><input class="input" v-model="search" placeholder="Nom ou spécialité"><div v-for="d in doctors" :key="d.id" class="list-row" @click="selected=d" style="cursor:pointer"><div><b>Dr. {{d.first_name}} {{d.last_name}}</b><div>{{d.doctor_profiles?.specialty||'Médecin'}}</div></div><span v-if="selected?.id===d.id" class="badge badge-green">Sélectionné</span></div></section><section class="card"><h3>Créneaux disponibles</h3><div v-if="!selected">Sélectionnez un médecin.</div><div v-for="s in slots" :key="s.id" class="slot" :class="{selected:slot?.id===s.id}" @click="slot=s"><b>{{new Date(s.start_time).toLocaleDateString('fr-FR')}}</b><span>{{new Date(s.start_time).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}}</span></div><textarea v-model="reason" class="input" placeholder="Motif de consultation" rows="4" style="margin-top:16px"></textarea><button class="btn btn-primary" :disabled="!slot||!reason||booking" @click="book">{{booking?'Réservation…':'Confirmer le rendez-vous'}}</button><p v-if="message" style="margin-top:12px">{{message}}</p></section></div></AppLayout></template>
<script setup lang="ts">import {ref,watch} from 'vue';import {useRouter} from 'vue-router';import AppLayout from '@/components/layout/AppLayout.vue';import {supabase} from '@/lib/supabase';import {useAuthStore} from '@/stores/auth';const auth=useAuthStore(),router=useRouter();const doctors=ref<any[]>([]),slots=ref<any[]>([]),selected=ref<any>(),slot=ref<any>(),search=ref(''),reason=ref(''),booking=ref(false),message=ref('');const loadDoctors=async()=>{let q=supabase.from('profiles').select('id,first_name,last_name,doctor_profiles!inner(specialty,verification_status)').eq('role','doctor').eq('doctor_profiles.verification_status','verified');if(search.value)q=q.or(`first_name.ilike.%${search.value}%,last_name.ilike.%${search.value}%`);const {data}=await q.limit(30);doctors.value=data||[]};watch(search,loadDoctors);watch(selected,async(d)=>{slot.value=null;if(!d)return;const {data}=await supabase.from('doctor_slots').select('*').eq('doctor_id',d.id).eq('status','available').gte('start_time',new Date().toISOString()).order('start_time').limit(30);slots.value=data||[]});loadDoctors();async function book(){if(!auth.user||!slot.value)return;booking.value=true;message.value='';const {error}=await supabase.rpc('book_appointment_slot',{p_patient_id:auth.user.id,p_slot_id:slot.value.id,p_reason:reason.value,p_mode:'in_person'});booking.value=false;if(error)message.value=error.message;else router.push({name:'appointments'})}</script>
